UPDATE sub_task
SET attempt_total = COALESCE(attempt_total, 0) + 1,
    update_time = #{now}
WHERE id = #{subTaskId}
  AND deleted = 0

UPDATE sub_task
SET attempt_total = 0,
    update_time = #{now}
WHERE id = #{subTaskId}
  AND deleted = 0

UPDATE sub_task
SET depends_on = #{dependsOnJson}::jsonb,
    update_time = #{now}
WHERE id = #{subTaskId}
  AND deleted = 0
